"""Careful HTTP client for the local order service.

Handles token refresh on 401, waits exactly as told on 429, retries transient
failures (5xx, connection errors, malformed JSON) and logs every attempt.
"""
import email.utils
import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


class Client:
    def __init__(self, log_path, max_attempts=60):
        self.token = None
        self.log_path = log_path
        self.max_attempts = max_attempts
        self.stats = {"requests": 0, "token_fetches": 0, "rate_limited": 0,
                      "unauthorized": 0, "server_errors": 0, "other_errors": 0,
                      "bad_body": 0, "total_wait_s": 0.0}

    def _log(self, rec):
        rec["ts"] = time.time()
        with open(self.log_path, "a") as f:
            f.write(json.dumps(rec) + "\n")

    def _raw(self, method, path, headers):
        req = urllib.request.Request(BASE + path, method=method, headers=headers,
                                     data=b"" if method == "POST" else None)
        self.stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()

    @staticmethod
    def _retry_after(headers, body):
        """Seconds to wait, from Retry-After header (seconds or HTTP date) or body."""
        h = {k.lower(): v for k, v in headers.items()}
        val = h.get("retry-after")
        if val is not None:
            val = val.strip()
            try:
                return max(0.0, float(val))
            except ValueError:
                try:
                    dt = email.utils.parsedate_to_datetime(val)
                    return max(0.0, dt.timestamp() - time.time())
                except Exception:
                    pass
        try:
            ra = json.loads(body).get("retry_after")
            if ra is not None:
                return max(0.0, float(ra))
        except Exception:
            pass
        return None

    def _wait(self, seconds, why):
        self.stats["total_wait_s"] += seconds
        time.sleep(seconds)

    def fetch_token(self):
        for attempt in range(1, self.max_attempts + 1):
            try:
                status, headers, body = self._raw("POST", "/token", {})
            except Exception as e:  # connection-level failure
                self.stats["other_errors"] += 1
                self._log({"op": "token", "attempt": attempt, "error": repr(e)})
                self._wait(min(2 ** attempt, 10), "conn")
                continue
            self._log({"op": "token", "attempt": attempt, "status": status,
                       "headers": headers, "body": body.decode("utf-8", "replace")[:500]})
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                    if isinstance(tok, str) and tok:
                        self.token = tok
                        self.stats["token_fetches"] += 1
                        return tok
                except Exception:
                    pass
                self.stats["bad_body"] += 1
                self._wait(1, "bad token body")
                continue
            if status == 429:
                self.stats["rate_limited"] += 1
                ra = self._retry_after(headers, body)
                self._wait(ra if ra is not None else 1.0, "429")
                continue
            if status >= 500:
                self.stats["server_errors"] += 1
            else:
                self.stats["other_errors"] += 1
            self._wait(min(2 ** attempt, 10), "token error")
        raise RuntimeError("could not obtain token")

