                    "GET", path, {"Authorization": "Bearer " + self.token})
            except Exception as e:
                self.stats["other_errors"] += 1
                self._log({"op": "get", "path": path, "attempt": attempt, "error": repr(e)})
                self._wait(min(2 ** attempt, 10), "conn")
                continue
            text = body.decode("utf-8", "replace")
            rec = {"op": "get", "path": path, "attempt": attempt, "status": status,
                   "token": self.token, "headers": headers}
            if status != 200:
                rec["body"] = text[:500]
            self._log(rec)
            if status == 200:
                try:
                    obj = json.loads(text)
                except Exception as e:
                    self.stats["bad_body"] += 1
                    self._log({"op": "bad_body", "path": path, "attempt": attempt,
                               "error": repr(e), "body": text[:500]})
                    self._wait(1, "bad json")
                    continue
                err = validate(obj) if validate else None
                if err:
                    self.stats["bad_body"] += 1
                    self._log({"op": "invalid_body", "path": path, "attempt": attempt,
                               "error": err, "body": text[:2000]})
                    self._wait(1, "invalid body")
                    continue
